`,(0,r.jsx)(i.li,{children:"Delegation emphasizes that our expertise and judgment remain the foundation of effective AI collaboration"}),`
`,(0,r.jsx)(i.li,{children:"Description involves clear communication that bridges our intentions and AI capabilities"}),`
`,(0,r.jsx)(i.li,{children:"Discernment requires thoughtful and critical evaluation of outputs to work within the systems constraints"}),`
`,(0,r.jsx)(i.li,{children:"Diligence ensures accountability, transparency, and responsibility in our AI work"}),`
`,(0,r.jsx)(i.li,{children:"The most powerful outcomes emerge when humans and AI build on each other's strengths"}),`
